object Main {
  def main(args: Array[String]): Unit = {
    val n = scala.io.StdIn.readInt()
    def createMultiplier(factor: Int): Int => Int = (x: Int) => x * factor
    val kaliDua = createMultiplier(2)
    val kaliTiga = createMultiplier(3)
    val kaliLima = createMultiplier(5)
    println(kaliDua(n) + " " + kaliTiga(n) + " " + kaliLima(n))
  }
}

