problems.solution:
object Main {
  def main(args: Array[String]): Unit = {
    val n = scala.io.StdIn.readInt()
    def applyTwice(f: Int => Int, x: Int): Int = f(f(x))
    val tambahSatu = applyTwice(x => x + 1, n)
    val kaliDua = applyTwice(x => x * 2, n)
    println(tambahSatu + " " + kaliDua)
  }
}
